-- SafetyTraining v20.054
-- Reconcile live road-sign / traffic-work training family under D.I. 22 January 2019.
-- Covers worker, supervisor, worker->supervisor bridge, and 5-year updates.

DO $do$
DECLARE r jsonb; c jsonb; v_lu uuid; v_luv uuid; v_course uuid; v_cv uuid; v_module uuid; v_practical boolean; v_content jsonb;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($units$
  [
    {"k":"road:worker:law","t":"Norme, rischi e responsabilità nei cantieri stradali","s":"Inquadrare Codice della strada, rischi per operatori/utenti e ruolo del lavoratore.","m":60,"v":"road-sign-v2","p":false,"f":["Codice della strada e regolamento","D.Lgs.81","rischio investimento","rischio trasmesso all’utenza","infortuni","comportamenti"],"case":"Una squadra deve intervenire su strada con traffico attivo: individuare rischi per operatori e utenti prima di posare il primo segnale."},
    {"k":"road:worker:signals","t":"Segnaletica temporanea, DPI e organizzazione della squadra","s":"Comprendere logica della segnaletica temporanea, alta visibilità, ruoli e comunicazione.","m":90,"v":"road-sign-v2","p":false,"f":["segnaletica temporanea","schemi","indumenti alta visibilità","squadra","comunicazione","presegnalazione"],"case":"Uno schema standard non entra nello spazio disponibile: riconoscere che non si improvvisa e che serve la soluzione coerente con categoria e scenario."},
    {"k":"road:worker:operations","t":"Norme operative per interventi programmati, mobili ed emergenze","s":"Preparare entrata, uscita, apposizione/rimozione e interventi urgenti in condizioni controllate.","m":90,"v":"road-sign-v2","p":false,"f":["veicolo operativo","entrata/uscita","bandieramento","cantiere mobile","emergenza","coordinamento"],"case":"Un veicolo deve entrare in area di lavoro su strada a scorrimento: definire comunicazione e sequenza per non sorprendere l’utenza."},
    {"k":"road:worker:practice","t":"Pratica: installazione, revisione, rimozione e cantiere mobile","s":"Eseguire le principali tecniche operative per diverse categorie di strada e per emergenze.","m":240,"v":"road-sign-v2","p":true,"f":["A-B-D","C-F extraurbane","E-F urbane","installazione","rimozione","revisione","cantieri mobili","emergenze"],"case":"Simulazione completa: squadra installa un cantiere, corregge una anomalia introdotta dal docente e rimuove la segnaletica in ordine sicuro."},
    {"k":"road:prep:law1","t":"Sistema di prevenzione, cantieri e responsabilità del preposto","s":"Inquadrare obblighi di sicurezza e funzione di vigilanza nelle attività stradali.","m":90,"v":"road-sign-v2","p":false,"f":["D.Lgs.81","preposto","cantieri temporanei/mobili","rischio traffico","dovere di intervento","coordinamento"],"case":"Un lavoratore propone una procedura più rapida ma diversa da quella pianificata: il preposto deve decidere e motivare."},
    {"k":"road:prep:law2","t":"Codice della strada, rischi per utenza e analisi degli eventi","s":"Applicare le regole stradali alle decisioni di pianificazione e controllo della squadra.","m":90,"v":"road-sign-v2","p":false,"f":["Codice strada","regolamento","categorie","cantieri","violazioni","incidenti","utenti vulnerabili"],"case":"Un cantiere crea una traiettoria poco leggibile per motociclisti: individuare responsabilità di pianificazione e correzione."},
    {"k":"road:prep:schemes","t":"Schemi segnaletici e scelta per categoria di strada","s":"Leggere e applicare il disciplinare tecnico evitando adattamenti intuitivi.","m":150,"v":"road-sign-v2","p":false,"f":["schemi temporanei","categorie A-B-C-D-E-F","visibilità","progressione segnali","spazi","velocità"],"case":"Confrontare due categorie di strada e motivare perché la stessa sequenza geometrica non è automaticamente trasferibile."},
    {"k":"road:prep:team","t":"Organizzazione squadra, comunicazione e gestione delle variazioni","s":"Pianificare ruoli, comunicazione, mezzi, DPI e criteri di stop per interventi programmati o urgenti.","m":150,"v":"road-sign-v2","p":false,"f":["briefing","ruoli","radio/segnali","bandierina","veicoli","alta visibilità","meteo","traffico","stop work"],"case":"Durante l’intervento aumenta improvvisamente il traffico e cala la visibilità: rivalutare configurazione e decidere se sospendere."},
    {"k":"road:prep:practice","t":"Pratica preposto: briefing, installazione/rimozione e gestione emergenza","s":"Dirigere una squadra in simulazione, controllando comunicazione, sequenza e sicurezza verso utenza e operatori.","m":240,"v":"road-sign-v2","p":true,"f":["briefing","supervisione","A-B-D","C-F","E-F","cantiere mobile","emergenza","feedback"],"case":"Il preposto riceve uno scenario con schema, squadra e mezzi; dirige l’installazione e interviene su una deviazione simulata."},
    {"k":"road:bridge:technical","t":"Integrazione tecnica: pianificazione e controllo del preposto","s":"Trasformare competenze operative del lavoratore in capacità di pianificazione, vigilanza e intervento.","m":60,"v":"road-sign-v2","p":false,"f":["ruolo preposto","scelta schema","briefing","verifica","deviazioni","stop"],"case":"Una squadra tecnicamente competente inizia a discostarsi dallo schema: il nuovo preposto deve intervenire senza limitarsi a partecipare."},
    {"k":"road:bridge:practice","t":"Pratica: comunicazione, simulazione e controllo della squadra","s":"Simulare briefing, conduzione, correzione ed emergenza dal punto di vista del preposto.","m":180,"v":"road-sign-v2","p":true,"f":["comunicazione","assegnazione ruoli","osservazione","correzione","emergenza","debriefing"],"case":"Role-play con due operatori: il preposto dirige installazione, gestisce un errore e chiude con verifica finale."},
    {"k":"road:upd:worker:review","t":"Aggiornamento tecnico: norme, schemi, DPI ed eventi","s":"Rivedere modifiche normative/tecniche e lezioni da incidenti, quasi incidenti e cambi di procedure.","m":120,"v":"road-sign-update-v2","p":false,"f":["novità","segnaletica","alta visibilità","mezzi","comunicazione","near miss","emergenze"],"case":"Dopo l’ultimo corso è cambiata la procedura di ingresso del mezzo: confrontare vecchia abitudine e nuova sequenza."},
    {"k":"road:upd:worker:practice","t":"Aggiornamento pratico: installazione, rimozione e scenario di emergenza","s":"Rinnovare tecniche operative e risposta a una variazione del traffico o dell’ambiente.","m":240,"v":"road-sign-update-v2","p":true,"f":["installazione","rimozione","cantiere mobile","comunicazione","emergenza","stop"],"case":"Simulazione con incremento del traffico e segnale spostato: la squadra deve riconoscere la perdita di controllo e ripristinare."},
    {"k":"road:upd:prep:review","t":"Aggiornamento preposto: norme, pianificazione e vigilanza","s":"Aggiornare capacità di scelta dello schema, briefing, controllo e gestione delle deviazioni.","m":180,"v":"road-sign-update-v2","p":false,"f":["novità","schemi","rischi","briefing","vigilanza","non conformità","near miss"],"case":"Analizzare un quasi incidente e stabilire cosa doveva essere previsto dal preposto prima e cosa va cambiato dopo."},
    {"k":"road:upd:prep:practice","t":"Aggiornamento pratico preposto: simulazione e gestione criticità","s":"Dirigere una simulazione con cambiamento di scenario, comunicazione e decisione di stop/ripresa.","m":180,"v":"road-sign-update-v2","p":true,"f":["simulazione","squadra","comunicazione","traffico","emergenza","stop/ripresa","debriefing"],"case":"Il docente introduce visibilità ridotta e perdita di comunicazione: il preposto deve fermare, riorganizzare e autorizzare la ripresa."}
  ]::jsonb) LOOP
    v_practical := (r->>'p')::boolean;
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    VALUES(r->>'k',r->>'t',r->>'s',(r->>'m')::int,'SafetyTraining road-sign-v2',array['safetytraining','road-sign','traffic-work'],true,jsonb_build_object('learner_ready',true,'teacher_ready',true,'practical_focus',v_practical,'didactic_version',r->>'v'))
    ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;
    v_content := jsonb_build_object(
      'case',r->>'case','norm','Decreto interministeriale 22 gennaio 2019, Allegati I e II; D.Lgs. 81/2008; Codice della strada e relativo regolamento per gli aspetti applicabili.',
      'quiz',jsonb_build_object('options',jsonb_build_array('Si accorciano le distanze a intuito','Si continua più velocemente','Si interrompe e si ripristina o ripianifica una configurazione conforme e controllata','Si fa affidamento solo sull’alta visibilità'),'question','Se traffico, spazio o visibilità cambiano e lo schema previsto non è più applicabile in sicurezza, cosa si fa?','explanation','La sicurezza dipende dalla coerenza della configurazione con strada e traffico reali; non è ammesso compensare una situazione non controllata con sola prudenza.','correct_index',2),
      'focus',r->'f','title',r->>'t','detail','Il lavoro in presenza di traffico richiede che segnaletica, veicoli, operatori e utenti siano trattati come un unico sistema dinamico. La procedura corretta deve essere leggibile con anticipo dall’utente della strada e contemporaneamente proteggere la squadra. Il corsista deve riconoscere quando traffico, visibilità, spazio o comunicazione non consentono più di applicare la configurazione pianificata e quindi richiedono stop e ripianificazione.','minutes',(r->>'m')::int,
      'quality',jsonb_build_object('learner_ready',true,'teacher_ready',true,'scenario_based',true,'practical_focus',v_practical),'summary',r->>'s',
      'visuals',jsonb_build_array('procedura-operativa-5-fasi.svg','stop-segnala-ripristina.svg','piramide-pericoli.svg'),
      'procedure',case when v_practical then jsonb_build_array('briefing e assegnazione ruoli','controllare veicoli, DPI, segnali e spazio operativo','eseguire installazione/intervento nella sequenza prevista','mantenere comunicazione e osservazione del traffico','rimuovere o ripristinare in ordine sicuro e fare debriefing') else jsonb_build_array('identificare categoria di strada e tipo di intervento','riconoscere rischi per operatori e utenti','scegliere schema/procedura prevista','definire ruoli, comunicazione e criteri di stop','verificare sul campo che la configurazione resti leggibile e controllata') end,
      'common_errors',jsonb_build_array('improvvisare uno schema perché manca spazio','iniziare prima del briefing','affidarsi soltanto al giubbetto alta visibilità','perdere comunicazione con la squadra e continuare','rimuovere la presegnalazione troppo presto'),
      'delivery_note','Il materiale completo resta consultabile. Prove pratiche/addestramento devono essere svolti in sedi dove siano ricreabili condizioni operative simili a quelle reali, senza essere sostituiti dalla sola consultazione digitale.',
      'guided_activity',jsonb_build_array('brief dello scenario','scelta dello schema e dei ruoli','esecuzione o decisione','variazione controllata','feedback su leggibilità, rischio e stop'),
      'didactic_version',r->>'v','final_assessment',false,
      'teacher_expansion',case when v_practical then 'Ricreare una sede operativa simulata coerente con una tipologia di strada senza esporre i discenti a traffico reale non controllato. Far eseguire individualmente/come squadra installazione, comunicazione e rimozione. Introdurre una variazione controllata e verificare la decisione di stop.' else 'Usare schemi del disciplinare, planimetrie e video/foto di cantieri. Far individuare cosa vede l’utente e cosa vede l’operatore. Chiedere sempre quale modifica del traffico o della visibilità rende lo schema non più applicabile.' end);
    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at) VALUES(v_lu,1,'draft',v_content,null)
      ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
    VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}')
    ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
  END LOOP;

  FOR c IN SELECT value FROM jsonb_array_elements($courses$
  [
    {"k":"segnaletica_stradale_lav_8h","t":"Segnaletica stradale in presenza di traffico – Lavoratori – 8h","d":"Formazione per lavoratori addetti alla pianificazione, controllo, apposizione, revisione e rimozione della segnaletica in presenza di traffico veicolare.","m":480,"v":"road-sign-v2","bp":"road_sign_worker_8h","basis":"D.I. 22 gennaio 2019, Allegato II","meta":{"legal_minutes":60,"technical_minutes":180,"practical_minutes":240,"attendance_min_pct":90,"intermediate_test_required":true,"final_practical_test_required":true}},
    {"k":"segnaletica_stradale_prep_12h","t":"Segnaletica stradale in presenza di traffico – Preposti – 12h","d":"Formazione completa per preposti addetti alle attività con segnaletica stradale in presenza di traffico veicolare.","m":720,"v":"road-sign-v2","bp":"road_sign_supervisor_12h","basis":"D.I. 22 gennaio 2019, Allegato II","meta":{"legal_minutes":180,"technical_minutes":300,"practical_minutes":240,"attendance_min_pct":90,"intermediate_test_required":true,"final_practical_test_required":true}},
    {"k":"segnaletica_stradale_prep_integ_4h","t":"Segnaletica stradale – Integrazione lavoratore → preposto – 4h","d":"Integrazione per chi ha già completato il percorso lavoratore e assume compiti di preposto: 1h tecnica + 3h comunicazione/simulazione pratica.","m":240,"v":"road-sign-v2","bp":"road_sign_supervisor_bridge_4h","basis":"D.I. 22 gennaio 2019, Allegato II punto 6.2","meta":{"technical_minutes":60,"practical_minutes":180,"requires_prior_worker_course":true,"final_practical_test_required":true}},
    {"k":"agg_segnaletica_stradale_lav_6h","t":"Aggiornamento segnaletica stradale – Lavoratori – 6h","d":"Aggiornamento quinquennale minimo di 6 ore per lavoratori addetti ad attività in presenza di traffico veicolare.","m":360,"v":"road-sign-update-v2","bp":"road_sign_worker_update_6h","basis":"D.I. 22 gennaio 2019, Allegato II punto 10","meta":{"renewal_months":60,"internal_theory_minutes":120,"internal_practical_minutes":240}},
    {"k":"agg_segnaletica_stradale_prep_6h","t":"Aggiornamento segnaletica stradale – Preposti – 6h","d":"Aggiornamento quinquennale minimo di 6 ore per preposti addetti ad attività in presenza di traffico veicolare.","m":360,"v":"road-sign-update-v2","bp":"road_sign_supervisor_update_6h","basis":"D.I. 22 gennaio 2019, Allegato II punto 10","meta":{"renewal_months":60,"internal_theory_minutes":180,"internal_practical_minutes":180}}
  ]::jsonb) LOOP
    INSERT INTO public.courses(stable_key,title,family,description,nominal_minutes,certification_mode,active,metadata)
    VALUES(c->>'k',c->>'t','Cantieri stradali e traffico',c->>'d',(c->>'m')::int,'internal_learning',true,jsonb_build_object('blueprint_key',c->>'bp','didactic_version',c->>'v','regulatory_basis',c->>'basis','material_complete',true,'requires_admin_review',true,'learner_catalog_hidden',true,'delivery_rules_are_metadata_only',true)||coalesce(c->'meta','{}'::jsonb))
    ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,family=excluded.family,description=excluded.description,nominal_minutes=excluded.nominal_minutes,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_course;
    INSERT INTO public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot,published_at)
    VALUES(v_course,1,'draft',jsonb_build_object('total_minutes',(c->>'m')::int,'didactic_version',c->>'v','material_complete',true),jsonb_build_object('basis',c->>'basis'),null)
    ON CONFLICT(course_id,version_number) DO UPDATE SET status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot,published_at=null;
  END LOOP;

  FOR c IN SELECT value FROM jsonb_array_elements($modules$
  [
    {"c":"segnaletica_stradale_lav_8h","mk":"road-law","mt":"Modulo giuridico-normativo – 1h","mp":1,"mm":60,"u":[["road:worker:law",1,false]]},
    {"c":"segnaletica_stradale_lav_8h","mk":"road-tech","mt":"Modulo tecnico – 3h","mp":2,"mm":180,"u":[["road:worker:signals",1,false],["road:worker:operations",2,false]]},
    {"c":"segnaletica_stradale_lav_8h","mk":"road-practice","mt":"Modulo pratico – 4h","mp":3,"mm":240,"u":[["road:worker:practice",1,true]]},
    {"c":"segnaletica_stradale_prep_12h","mk":"roadp-law","mt":"Modulo giuridico-normativo – 3h","mp":1,"mm":180,"u":[["road:prep:law1",1,false],["road:prep:law2",2,false]]},
    {"c":"segnaletica_stradale_prep_12h","mk":"roadp-tech","mt":"Modulo tecnico – 5h","mp":2,"mm":300,"u":[["road:prep:schemes",1,false],["road:prep:team",2,false]]},
    {"c":"segnaletica_stradale_prep_12h","mk":"roadp-practice","mt":"Modulo pratico – comunicazione e simulazione – 4h","mp":3,"mm":240,"u":[["road:prep:practice",1,true]]},
    {"c":"segnaletica_stradale_prep_integ_4h","mk":"road-bridge","mt":"Integrazione preposto – 4h","mp":1,"mm":240,"u":[["road:bridge:technical",1,false],["road:bridge:practice",2,true]]},
    {"c":"agg_segnaletica_stradale_lav_6h","mk":"road-upd-worker","mt":"Aggiornamento lavoratori – 6h","mp":1,"mm":360,"u":[["road:upd:worker:review",1,false],["road:upd:worker:practice",2,true]]},
    {"c":"agg_segnaletica_stradale_prep_6h","mk":"road-upd-prep","mt":"Aggiornamento preposti – 6h","mp":1,"mm":360,"u":[["road:upd:prep:review",1,false],["road:upd:prep:practice",2,true]]}
  ]::jsonb) LOOP
    SELECT cv.id INTO v_cv FROM public.course_versions cv JOIN public.courses co ON co.id=cv.course_id WHERE co.stable_key=c->>'c' AND cv.version_number=1;
    INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes)
    VALUES(v_cv,c->>'mk',c->>'mt',(c->>'mp')::int,(c->>'mm')::int)
    ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=excluded.position,nominal_minutes=excluded.nominal_minutes RETURNING id INTO v_module;
    FOR r IN SELECT value FROM jsonb_array_elements(c->'u') LOOP
      SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>0;
      INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
      VALUES(v_module,v_luv,(r->>1)::int,true,0,true,jsonb_build_object('material_complete',true,'practical_or_guided',(r->>2)::boolean))
      ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules;
    END LOOP;
  END LOOP;
END $do$;
